function nav:DiscardCandidate(reason)
    if not self.search then return false end
    self.generation = self.generation + 1
    self:CancelLocalPath()
    self.search:Cancel()
    self.search = nil
    self.waypointPendingLeg, self.waypointPreview, self.pausedWaypointSearch = nil, nil, nil
    CancelTimer(self._searchTimer)
    self._searchTimer = nil
    self.recomputeKeepingPath, self.recomputeKeepingDirect = nil, nil
    self.dirty = true
    self.lastCandidateDiscard = { reason = reason, queuedSteps = #self.queue, generation = self.generation }
    return true
end--[[APR_DIAG]]; nav.DiscardCandidate = APRTrace("APR-Core/features/navigation/controller/NavigationLifecycle.lua:151:nav:DiscardCandidate#4", nav.DiscardCandidate)--[[/APR_DIAG]]

function nav:BeginWorldLoading(event)
    if not self.worldLoading then self:SaveWaypointJourney(true) end
    self.lastWalkCorridor = nil
    self.walkingObservation = nil
    local service = APR.Services and APR.Services:GetStep()
    if service then service.serviceItinerary = nil end
    local alreadyLoading = self.worldLoading
    if event == "PLAYER_LEAVING_WORLD" then
        self._outsideWorld = true
    else
        self._loadingScreen = true
    end
    self.worldLoading, self.lastWorldEvent = true, event
    if self.RefreshActivity then self:RefreshActivity() end
    if not alreadyLoading then
        -- Keep the published route in memory, including its live predicates.
        -- Only the candidate measured before departure becomes obsolete.
        -- A landing leg is measured from its fixed anchor and remains useful
        -- on either shore. Searches from the player still become obsolete.
        if not (self.search and self.waypointPendingLeg and self.waypointPendingLeg.before) then
            self:DiscardCandidate("world_loading")
        end
        CancelTimer(self._stepCheckTimer)
        self._stepCheckTimer = nil
        CancelTimer(self._cooldownRefreshTimer)
        self._cooldownRefreshTimer = nil
        self._resumeAfterTransition = true
    end
end--[[APR_DIAG]]; nav.BeginWorldLoading = APRTrace("APR-Core/features/navigation/controller/NavigationLifecycle.lua:166:nav:BeginWorldLoading#5", nav.BeginWorldLoading)--[[/APR_DIAG]]

function nav:EndWorldLoading(event)
    local wasLoading = self.worldLoading
    if event == "PLAYER_ENTERING_WORLD" then
        self._outsideWorld = false
    else
        self._loadingScreen = false
    end
    self.worldLoading = self._outsideWorld == true or self._loadingScreen == true
    self.lastWorldEvent = event
    if self.worldLoading then return end
    -- The settling allowance starts on return, not before a long loading
    -- screen. A duplicate return event must not renew it indefinitely.
    if wasLoading then self._transitionProbe = nil end
    self:ForceRefresh("world_transition")
    local restored = APR.Services and APR.Services.RestoreWaypoint and APR.Services:RestoreWaypoint()
    if not restored then self:RequestUpdate() end
    if self.pausedWaypointSearch then
        self._searchTimer = C_Timer.NewTimer(Constants.WAYPOINT_RESUME_DELAY_SECONDS, self.pausedWaypointSearch)
        self.pausedWaypointSearch = nil
    end
    if self.RefreshActivity then self:RefreshActivity() end
end--[[APR_DIAG]]; nav.EndWorldLoading = APRTrace("APR-Core/features/navigation/controller/NavigationLifecycle.lua:196:nav:EndWorldLoading#6", nav.EndWorldLoading)--[[/APR_DIAG]]

function nav:InvalidatePathCache(reason)
    if reason == "QUEST_LOG_UPDATE" and APR.NavigationData and APR.NavigationData.profile == "forever" then
        local inputs = self._routeInputs
        if
            inputs
            and inputs.step
            and inputs.step._mapWaypoint
            and inputs.geometryRevision == APR.navigationGeometryRevision
            and self:IsObjectiveCurrent(inputs)
        then
            -- A journal refresh does not move a manual pin. Quest lifecycle
            -- events and changed map geometry still invalidate its itinerary.
            return
        end
    end
    local serviceRequest = APR.Services and APR.Services.request
    if serviceRequest and serviceRequest.profile == "forever" and Constants.serviceAccessChanges[reason] then
        serviceRequest.invalidated = true
    end
    if reason == "service_started" and APR.Services then
        local step = APR.Services:GetStep()
        if step and step.serviceItinerary then step.serviceGeometry = APR.navigationGeometryRevision end
    end
    if
        APR.Services
        and APR.Services.CancelTraining
        and (
            reason == "SKILL_LINES_CHANGED"
            or reason == "SPELLS_CHANGED"
            or reason == "PLAYER_LEVEL_UP"
            or reason == "UPDATE_FACTION"
            or reason == "QUEST_LOG_UPDATE"
            or reason == "QUEST_TURNED_IN"
            or reason == "QUEST_REMOVED"
        )
    then
        APR.Services:CancelTraining()
    end
    self.dirty, self._mountCapability = true, nil
    self.lastInvalidation = reason or "refresh"
    -- Quest/bag/cooldown events interleave with loading. They cannot erase an
    -- arrival still awaiting validation or renew its bounded settling window.
    if reason == "world_transition" then
        self._resumeAfterTransition = true
        self:BeginTransitionProbe(self:GetActiveStep())
    end
end--[[APR_DIAG]]; nav.InvalidatePathCache = APRTrace("APR-Core/features/navigation/controller/NavigationLifecycle.lua:219:nav:InvalidatePathCache#7", nav.InvalidatePathCache)--[[/APR_DIAG]]

function nav:ForceRefresh(reason) self:InvalidatePathCache(reason) end--[[APR_DIAG]]; nav.ForceRefresh = APRTrace("APR-Core/features/navigation/controller/NavigationLifecycle.lua:267:nav:ForceRefresh#8", nav.ForceRefresh)--[[/APR_DIAG]]

function nav:RequestUpdate()
    if not Enabled() then
        self:RefreshActivity()
        return
    end
    if APR.routeValidationPending or APR.routeValidationFailed then return end
    if self.worldLoading then return end
    if self._stepCheckTimer then
        if ContextCurrent(self._scheduledStepContext) then return end
        CancelTimer(self._stepCheckTimer)
    end
    local context = CaptureContext()
    self._scheduledStepContext = context
    local timer
    local changedStep = self.reason == "step_changed"
        and APR.NavigationData
        and APR.NavigationData.profile == "forever"
        and not (APR.stepUpdatePending or APR.stepUpdateTimer or APR.stepUpdateRunning)
    timer = C_Timer.NewTimer(changedStep and 0 or Constants.STEP_CHECK_DELAY_SECONDS, --[[APR_DIAG]]APRTrace("APR-Core/features/navigation/controller/NavigationLifecycle.lua:287:callback#10", --[[/APR_DIAG]]function()
        if self._stepCheckTimer ~= timer then return end
        self._stepCheckTimer = nil
        if ContextCurrent(context) then self:Update(context) end
        self:RefreshActivity()
    end--[[APR_DIAG]])--[[/APR_DIAG]])
    self._stepCheckTimer = timer
end--[[APR_DIAG]]; nav.RequestUpdate = APRTrace("APR-Core/features/navigation/controller/NavigationLifecycle.lua:269:nav:RequestUpdate#9", nav.RequestUpdate)--[[/APR_DIAG]]
nav.RequestRouteCheck, nav.ScheduleRouteCheck = nav.RequestUpdate, nav.RequestUpdate

function nav:RequestCooldownRefresh()
    if self.worldLoading or not Enabled() then return end
    if self._cooldownRefreshTimer then return end
    local adapter = APR.NavigationAdapter
    if not adapter or not adapter.CreateCooldownCheck then return end
    -- Most cooldown events belong to combat spells. Inspect only travel actions
    -- already seen in the catalogue, in small batches, before dirtying a route.
    local timer
    local check
    local function refresh()
        if self._cooldownRefreshTimer ~= timer then return end
        self._cooldownRefreshTimer = nil
        if not Enabled() then return end
        if self.search then
            self:RequestCooldownRefresh()
            return
        end
        check = check or adapter:CreateCooldownCheck()
        local state, changed = check:Step(Constants.COOLDOWN_SLICE_OPERATIONS, Constants.COOLDOWN_SLICE_MS)
        if state == "planning" then
            timer = C_Timer.NewTimer(0, refresh)
            self._cooldownRefreshTimer = timer
        elseif changed then
            self:InvalidatePathCache()
            self:RequestUpdate()
        end
    end--[[APR_DIAG]]; refresh = APRTrace("APR-Core/features/navigation/controller/NavigationLifecycle.lua:306:refresh#12", refresh)--[[/APR_DIAG]]
    timer = C_Timer.NewTimer(Constants.COOLDOWN_REFRESH_DELAY_SECONDS, refresh)
    self._cooldownRefreshTimer = timer
end--[[APR_DIAG]]; nav.RequestCooldownRefresh = APRTrace("APR-Core/features/navigation/controller/NavigationLifecycle.lua:297:nav:RequestCooldownRefresh#11", nav.RequestCooldownRefresh)--[[/APR_DIAG]]

